O=Path('work_output');(O/'variants/ht').mkdir(exist_ok=True);a=np.array(Image.open(O/'sources/neutral.png').convert('RGBA'));H,W=a.shape[:2];piv=np.array([615,510]);shift=np.array([35,17]);mask=Image.new('L',(W,H));ImageDraw.Draw(mask).polygon([(420,376),(474,380),(527,454),(576,465),(616,482),(624,535),(582,551),(540,547),(530,531),(493,529),(480,490),(420,418)],fill=255);m=np.array(mask)>0;limb=np.zeros_like(a);limb[m]=a[m];fixed=a.copy();fixed[m]=0
